use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").trim().parse().unwrap();
    let mut output = String::new();

    for _ in 0..n {
        let line = lines.next().unwrap_or("");
        let mut stack = Vec::new();
        let mut valid = true;

        for bracket in line.chars() {
            match bracket {
                '(' | '[' | '{' => stack.push(bracket),
                ')' => {
                    if stack.pop() != Some('(') {
                        valid = false;
                        break;
                    }
                }
                ']' => {
                    if stack.pop() != Some('[') {
                        valid = false;
                        break;
                    }
                }
                '}' => {
                    if stack.pop() != Some('{') {
                        valid = false;
                        break;
                    }
                }
                _ => unreachable!(),
            }
        }

        if !stack.is_empty() {
            valid = false;
        }

        output.push_str(if valid { "valid\n" } else { "invalid\n" });
    }

    print!("{output}");
}

