use std::io::{self, Read};

fn append_run(output: &mut String, start: i64, end: i64) {
    if !output.is_empty() {
        output.push(',');
    }

    let length_at_least_three = start.checked_add(2).is_some_and(|value| value <= end);
    if length_at_least_three {
        output.push_str(&start.to_string());
        output.push('-');
        output.push_str(&end.to_string());
    } else {
        output.push_str(&start.to_string());
        if end != start {
            output.push(',');
            output.push_str(&end.to_string());
        }
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap().parse().unwrap();

    if n == 0 {
        println!();
        return;
    }

    let first: i64 = values.next().unwrap().parse().unwrap();
    let mut start = first;
    let mut end = first;
    let mut output = String::new();

    for _ in 1..n {
        let current: i64 = values.next().unwrap().parse().unwrap();
        if end.checked_add(1) == Some(current) {
            end = current;
        } else {
            append_run(&mut output, start, end);
            start = current;
            end = current;
        }
    }

    append_run(&mut output, start, end);
    println!("{output}");
}

